//! Source spans and diagnostic codes.
//!
//! Blueprint 23.03 ("Compiler diagnostics") asks for domain-specific diagnostics carrying a stable
//! code, the offending names, and a suggested fix — its worked example is `WEAVE-E2407: authority
//! escalation through delegation`. The audience matters: WeaveLang is expected to be *generated by
//! an LLM* (23.02), so the compiler's error is the feedback signal an agent iterates against. An
//! error that says only "syntax error" gives an agent nothing to act on, so every error in this
//! crate carries a span, the token or name that broke, and a stable code.
//!
//! Codes are allocated in blocks so that a code identifies the phase that rejected the program:
//!
//! | Block | Phase |
//! |---|---|
//! | `WEAVE-E1xxx` | lexing |
//! | `WEAVE-E2xxx` | parsing |
//! | `WEAVE-E3xxx` | lowering to WeaveIR (23.03 phases 1–4) |
//! | `WEAVE-E4xxx` | the cognitive type system (23.04) |
//! | `WEAVE-E5xxx` | operational semantics and invariants (23.34) |
//!
//! Codes are part of the crate's contract: a test or an agent may match on them, so a code is
//! never reassigned to a different meaning.

use serde::{Deserialize, Serialize};

/// A half-open byte range in one source file, with the line and column of its start.
///
/// Byte offsets rather than character offsets, because the lexer works over bytes and slicing the
/// source for an error message must not be able to panic on a multi-byte boundary; the recorded
/// offsets always land on character boundaries because they come from character iteration.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
pub struct Span {
    pub start: usize,
    pub end: usize,
    pub line: u32,
    pub column: u32,
}

impl Span {
    pub fn new(start: usize, end: usize, line: u32, column: u32) -> Self {
        Span {
            start,
            end,
            line,
            column,
        }
    }

    /// A zero-width span, used for the synthetic end-of-file token.
    pub fn empty_at(offset: usize, line: u32, column: u32) -> Self {
        Span::new(offset, offset, line, column)
    }

    /// The smallest span covering both, keeping the earlier line and column.
    pub fn merge(self, other: Span) -> Span {
        if self.start <= other.start {
            Span {
                start: self.start,
                end: self.end.max(other.end),
                line: self.line,
                column: self.column,
            }
        } else {
            other.merge(self)
        }
    }

    /// The source text this span covers, or `None` when the span does not fit the given source.
    ///
    /// Returns `None` rather than panicking so that rendering a diagnostic can never itself fail:
    /// a span carried across from a different file is a bug, but a bug that must not abort the
    /// compiler while it is reporting another error.
    pub fn slice(self, source: &str) -> Option<&str> {
        source.get(self.start..self.end)
    }
}

impl std::fmt::Display for Span {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}:{}", self.line, self.column)
    }
}

/// A stable machine-readable code for one rejection reason.
///
/// Every error type in this crate implements this, so a caller can route on the code without
/// matching the error's variants, and a diagnostic's wording can change without breaking anyone.
pub trait Diagnostic {
    /// The `WEAVE-Ennnn` code for this rejection.
    fn code(&self) -> &'static str;

    /// Where in the source the rejection happened, when the phase knows.
    ///
    /// Lowering and semantics errors that describe a whole program rather than one construct
    /// return `None`; that is honest, and preferable to attributing a whole-program property to an
    /// arbitrary token.
    fn span(&self) -> Option<Span>;
}

/// Renders a diagnostic in the shape 23.03 asks for: code, message, and the offending source line.
pub fn render(diagnostic: &dyn Diagnostic, message: &str, source: &str) -> String {
    let mut out = format!("{}: {}", diagnostic.code(), message);
    if let Some(span) = diagnostic.span() {
        out.push_str(&format!("\n  at line {} column {}", span.line, span.column));
        if let Some(text) = span.slice(source) {
            if !text.is_empty() {
                out.push_str(&format!("\n  {text}"));
            }
        }
    }
    out
}
